export type ParsedRecordSaleInstruction<
  TProgram extends string = typeof KOLAB_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    verifier: TAccountMetas[0];
    payer: TAccountMetas[1];
    config: TAccountMetas[2];
    campaign: TAccountMetas[3];
    enrollment: TAccountMetas[4];
    /** One per order ref: a replayed webhook fails here instead of paying twice. */
    saleReceipt: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: RecordSaleInstructionData;
};

export function parseRecordSaleInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRecordSaleInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 7,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      verifier: getNextAccount(),
      payer: getNextAccount(),
      config: getNextAccount(),
      campaign: getNextAccount(),
      enrollment: getNextAccount(),
      saleReceipt: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRecordSaleInstructionDataDecoder().decode(instruction.data),
  };
}
